INSERT INTO catalogue_listing (id, provider_org_id, country_code, region_id, category, title, description, languages, min_age, difficulty, accessibility, min_party, max_party, duration_minutes, service_tier, status, image_url) VALUES
  ('aa300001-cc00-0000-0000-000000000001', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Merzouga Dune Buggy Tour', 'A thrilling 2-hour dune buggy tour through the Erg Chebbi dunes, suitable for beginners.', ARRAY['en','fr','es','ary-Latn'], 16, 3, '{}', 1, 4, 120, 2, 'active', 'https://images.pexels.com/photos/11294565/pexels-photo-11294565.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300002-cc00-0000-0000-000000000002', '5a9a0005-0000-0000-0000-000000000005', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Desert Yoga at Sunrise', 'A gentle sunrise yoga session on the dunes, suitable for all levels. Mats and tea included.', ARRAY['en','fr','es','ary-Latn','ber'], 10, 1, '{}', 1, 10, 60, 2, 'active', 'https://images.pexels.com/photos/38277704/pexels-photo-38277704.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300003-cc00-0000-0000-000000000003', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Merzouga Village Bike Tour', 'A 2-hour bike ride through Merzouga village and surrounding palm groves, with a local guide.', ARRAY['en','fr','ary-Latn','ber'], 10, 2, '{}', 1, 8, 120, 1, 'active', 'https://images.pexels.com/photos/18742776/pexels-photo-18742776.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300004-cc00-0000-0000-000000000004', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Fossil Hunting in Erfoud', 'A half-day fossil hunting excursion near Erfoud, searching for trilobites and ammonites.', ARRAY['en','fr','es','ary-Latn','ber'], 8, 2, '{}', 1, 6, 180, 1, 'active', 'https://images.pexels.com/photos/18742776/pexels-photo-18742776.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300005-cc00-0000-0000-000000000005', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Khamlia Village Cultural Visit', 'A guided visit to Khamlia village, meeting Gnawa musicians and learning about their heritage.', ARRAY['en','fr','es','ary-Latn','ber'], 5, 1, '{}', 1, 10, 120, 2, 'active', 'https://images.pexels.com/photos/30374209/pexels-photo-30374209.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300006-cc00-0000-0000-000000000006', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Palm Grove Oasis Walk', 'A guided walk through the Tafilalt palm grove, learning about date farming and oasis life.', ARRAY['en','fr','es','ary-Latn','ber'], 8, 2, '{}', 1, 10, 120, 1, 'active', 'https://images.pexels.com/photos/11387356/pexels-photo-11387356.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300007-cc00-0000-0000-000000000007', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Nomad Family Visit', 'Visit a nomadic Berber family in their desert tent, share tea and learn about their way of life.', ARRAY['en','fr','ary-Latn','ber'], 5, 1, '{}', 1, 6, 90, 2, 'active', 'https://images.pexels.com/photos/18742776/pexels-photo-18742776.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300008-cc00-0000-0000-000000000008', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Sijilmassa Ruins Visit', 'A guided visit to the ruins of Sijilmassa, the medieval caravan city that controlled the gold trade.', ARRAY['en','fr','es','ary-Latn','ber'], 10, 1, '{}', 1, 8, 90, 2, 'active', 'https://images.pexels.com/photos/18742776/pexels-photo-18742776.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300009-cc00-0000-0000-000000000009', 'b3333333-0000-0000-0000-000000000003', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Desert Pizza Dinner', 'Traditional medfouna — Berber desert pizza — baked in the sand, served with salads and tea.', ARRAY['en','fr','ary-Latn','ber'], 5, 1, '{}', 1, 10, 90, 2, 'active', 'https://images.pexels.com/photos/2287528/pexels-photo-2287528.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa30000a-cc00-0000-0000-00000000000a', 'b3333333-0000-0000-0000-000000000003', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Dates & Tea Tasting', 'Taste 8 varieties of dates from the Tafilalt oasis, paired with Moroccan mint tea and nuts.', ARRAY['en','fr','ary-Latn','ber'], 5, 1, '{}', 1, 10, 60, 1, 'active', 'https://images.pexels.com/photos/30906051/pexels-photo-30906051.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa30000b-cc00-0000-0000-00000000000b', 'b3333333-0000-0000-0000-000000000003', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Berber Breakfast in the Desert', 'A traditional Berber breakfast of msemen, olive oil, honey and tea, served at a desert camp.', ARRAY['en','fr','ary-Latn','ber'], 5, 1, '{}', 1, 8, 60, 1, 'active', 'https://images.pexels.com/photos/30906049/pexels-photo-30906049.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa30000c-cc00-0000-0000-00000000000c', '5a9a0005-0000-0000-0000-000000000005', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Erg Chebbi Premium Camp (per night)', 'A premium desert camp with private tents, en-suite bathrooms and gourmet dinner.', ARRAY['en','fr','es','it','ary-Latn','ber'], 0, 1, '{}', 1, 6, 1440, 4, 'active', 'https://images.pexels.com/photos/9349466/pexels-photo-9349466.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa30000d-cc00-0000-0000-00000000000d', '5a9a0005-0000-0000-0000-000000000005', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Merzouga Guesthouse (per night)', 'A simple guesthouse in Merzouga village with AC, breakfast and rooftop terrace.', ARRAY['en','fr','ary-Latn','ber'], 0, 1, '{}', 1, 4, 1440, 2, 'active', 'https://images.pexels.com/photos/15531325/pexels-photo-15531325.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa30000e-cc00-0000-0000-00000000000e', '5a9a0005-0000-0000-0000-000000000005', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Merzouga Oasis Eco-Lodge (per night)', 'An eco-lodge at the oasis edge with organic meals, garden and dune views.', ARRAY['en','fr','es','ary-Latn','ber'], 0, 1, '{}', 1, 6, 1440, 3, 'active', 'https://images.pexels.com/photos/10573397/pexels-photo-10573397.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa30000f-cc00-0000-0000-00000000000f', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Erg Chebbi Dunes Panoramic Tour', 'A 3-hour tour to the best viewpoints of the Erg Chebbi dunes, by 4x4 and on foot.', ARRAY['en','fr','es','ary-Latn','ber'], 5, 2, '{}', 1, 8, 180, 2, 'active', 'https://images.pexels.com/photos/28356796/pexels-photo-28356796.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300010-cc00-0000-0000-000000000010', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Rissani Souk Tour', 'A guided tour of the Rissani souk, one of the last authentic desert markets, held 3 days a week.', ARRAY['en','fr','es','ary-Latn','ber'], 10, 2, '{}', 1, 8, 120, 1, 'active', 'https://images.pexels.com/photos/22711558/pexels-photo-22711558.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300011-cc00-0000-0000-000000000011', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Merzouga Lake Day Tour (Seasonal)', 'Visit the seasonal lake near Merzouga, a birdwatching paradise when it fills with water.', ARRAY['en','fr','es','ary-Latn','ber'], 8, 1, '{}', 1, 10, 120, 1, 'active', 'https://images.pexels.com/photos/11387356/pexels-photo-11387356.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300012-cc00-0000-0000-000000000012', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Khettara Underground Water Tour', 'A guided tour of the ancient khettara underground water channels that fed the oasis for centuries.', ARRAY['en','fr','es','ary-Latn','ber'], 10, 2, '{}', 1, 8, 90, 2, 'active', 'https://images.pexels.com/photos/18742776/pexels-photo-18742776.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300013-cc00-0000-0000-000000000013', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Jorf Palm Grove & Pottery Tour', 'A tour of the Jorf palm grove and traditional pottery workshops across the river from Merzouga.', ARRAY['en','fr','es','ary-Latn','ber'], 8, 1, '{}', 1, 8, 120, 1, 'active', 'https://images.pexels.com/photos/32422996/pexels-photo-32422996.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300014-cc00-0000-0000-000000000014', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Desert Bread Baking Workshop', 'Learn to bake traditional Berber bread (medfouna) in the hot sand of the Sahara.', ARRAY['en','fr','es','ary-Latn','ber'], 8, 1, '{}', 1, 8, 90, 1, 'active', 'https://images.pexels.com/photos/2287528/pexels-photo-2287528.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300015-cc00-0000-0000-000000000015', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Berber Jewelry Workshop', 'Learn traditional Berber silver jewelry techniques with a local artisan in Khamlia.', ARRAY['en','fr','es','ary-Latn','ber'], 12, 2, '{}', 1, 4, 120, 2, 'active', 'https://images.pexels.com/photos/21326994/pexels-photo-21326994.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300016-cc00-0000-0000-000000000016', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Gnawa Drum Workshop', 'Learn to play the krakebs (Gnawa castanets) with a master musician in Khamlia village.', ARRAY['en','fr','es','ary-Latn','ber'], 8, 1, '{}', 1, 10, 60, 1, 'active', 'https://images.pexels.com/photos/12585023/pexels-photo-12585023.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300017-cc00-0000-0000-000000000017', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Desert Weaving Workshop', 'Learn traditional desert weaving techniques using palm fibres and wool with local women.', ARRAY['en','fr','ary-Latn','ber'], 10, 1, '{}', 1, 6, 120, 1, 'active', 'https://images.pexels.com/photos/28582586/pexels-photo-28582586.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa300018-cc00-0000-0000-000000000018', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Sand Painting Workshop', 'Create art using the naturally coloured sands of the Sahara, with a local artist.', ARRAY['en','fr','es','ary-Latn'], 8, 1, '{}', 1, 8, 90, 1, 'active', 'https://images.pexels.com/photos/32422996/pexels-photo-32422996.jpeg?auto=compress&cs=tinysrgb&h=650&w=940')
